export const SEED_ITEMS: Item[] = [{"n":1,"t":"Approved sample tersedia dari Engineering","r":"1. Sample yang digunakan benar sesuai item yang sedang jalan.\n2. Label hijau pengisian lengkap beserta verifikasinya"},{"n":2,"t":"(QAFA) Sample acuan / FRA sesuai Approved Sample","r":"1. FRA tersedia dan sesuai item yang sedang jalan dan\n2. Pengisian label FRA lengkap dan benar sesuai sample.\n3. Kualitas FRA sesuai dengan approved sample."},{"n":3,"t":"Produk yang sedang berjalan sesuai dengan FRA dan toleransi / shade band","r":"1. Identitas Item yang berjalan sesuai dengan RHHP, FRA, dan approved sample\n2. Kualitas produk yang ada di green bin/ palet sesuai dengan FRA, sample dan shadeband (jika ada) (untuk retail/pcs: sampling 10, untuk sheet: sampling 2)"},{"n":4,"t":"Toleransi atau limit sample defect tersedia","r":"1. Limit sample, Shadeband, sample defect yang digunakan sesuai dengan produknya\n2. Limit sample hanya boleh di ACC oleh SPV - Manager QA/QC, PE dan Plant Manager\n3. Shadeband yang digunakan sudah di verifikasi oleh PE & Quality."},{"n":5,"t":"Reject telah dicatat dengan benar per 2 jam","r":"1. Laporan reject workcenter tersedia \n2. Pengisian reject workcenter lengkap dan benar\n3. Kode reject dan qty reject dengan aktual barang reject sesuai."},{"n":6,"t":"Reject tidak melebihi standard yang sudah ditentukan","r":"Printing: 5000 ppm\nDie cut: 3000 ppm\nProses lain: 2000 ppm\nIM: 3000 ppm\nppm pada laporan reject workcenter (kecuali reject setting)"},{"n":7,"t":"Parameter kualitas tersedia di area kerja (CTQ & Visual Defect)","r":"1. CTQ & Visual Defect tersedia, benar, lengkap, dan diketahui operator di area kerja\n2. Operator mengetahui point-point CTQ & Visual Defect yang tersedia di area kerja"},{"n":8,"t":"Parameter proses (CTP) dan prosedur/AK dipenuhi","r":"1. CTP & AK tersedia, benar, lengkap, dan diketahui operator di area kerja\n2. Operator mengetahui point-point CTP & AK yang tersedia di area kerja"},{"n":9,"t":"Andon yang tesedia berfungsi dan sesuai keadaan aktual","r":"1. Operator mengerti penggunaan dan fungsi andon yang ada di mesin/area\n2. Andon sesuai dengan keadaan aktual"},{"n":10,"t":"Aktual produksi mengikuti Layout IE","r":"1. Item yang berjalan sesuai dengan layout\n2. Jumlah dan jobdesc operator sesuai dengan layout \n3. Layout IE sesuai RHHP"},{"n":11,"t":"Kondisi mesin dan tools beroperasi dengan baik dan sesuai dengan toleransi atau batasan tertentu","r":"1. Pengecekan part-part mesin dan tools sesuai dengan parameter\n2. Bagian-bagian mesin dan tools berfungsi dengan benar"},{"n":12,"t":"Defect produk telah dipisahkan atau diberi tanda/ Barang yang sudah dihold tidak melebihi 1x24 jam","r":"1. Barang hold & reject tersegregasi dengan benar sesuai dengan tempatnya\n2. Barang reject /hold ada label identitas dengan isi yang benar dan jelas\n3. Barang hold dengan issue quality harus diselesaikan dalam 1x24 jam"},{"n":13,"t":"Red Bin / visual control dilakukan sesuai standar","r":"1. Red bin/visual control digunakan sesuai fungsi\n2. Isi red bin/visual control tidak boleh melebihi ppm standard."},{"n":14,"t":"AM/TPM Harian Mesin dilakukan sesuai jadwal","r":"1. AM/TPM Harian tersedia di setiap mesin dan point-point AM sesuai dengan mesinnya\n2. AM/TPM Harian diisi/ceklis sesuai dengan jadwal\n3. Operator melakukan TPM dengan benar (cek point TPM dan interview operator)"},{"n":15,"t":"Jadwal Produksi dan RHHP sesuai","r":"1. RHHP tersedia\n2. Produk yang sedang berjalan sesuai dengan RHHP (tidak ditulis manual oleh operator)\n3. Pengisian RHHP benar, diisi per jam, dan sudah diverifikasi oleh planner & spv"},{"n":16,"t":"(QAFA) Lembar checksheet diisi tepat waktu dan benar sesuai dengan RHHP","r":"1. Checksheet yang digunakan sesuai dengan proses dan acuan kerja\n2. Pengisian checksheet benar dan lengkap sesuai produk yang sedang proses (termasuk nama supplier & no lot/batch)\n3. Operator mengetahui point-point pada checksheet dan dilakukan dengan benar"},{"n":17,"t":"No. SPK/Lot/batch/PO tersedia untuk traceability","r":"1. No. SPK/Lot/batch/PO tercantum pada RHHP dan checksheet\n2. No. SPK/PO pada checksheet sesuai dengan RHHP \n3. No.Lot/Batch material yang digunakan tercantum pada checksheet dan sesuai dengan aktual.\n4. Penulisan & penggunaan material di actual tercatat pada checklist dokumen/checksheet sesuai dengan material yang sudah diapproved oleh customer/sample awal (cek NPOF)"},{"n":18,"t":"Material yang digunakan sesuai sudah pass inspeksi incoming","r":"Cek report incoming"},{"n":19,"t":"Jadwal Gemba / 5R / Kebersihan tersedia","r":"1. Ceklist 5R tersedia di setiap mesin/area \n2. Ceklist 5R sesuai dengan jadwal\n3. Operator melakukan 5R dengan benar (cek point 5R dan interview operator)"},{"n":20,"t":"(QAFA) Perbaikan proses / Kaizen dilakukan secara kontinyu","r":"1. Ada kaizen di area\n2. Action Plan dari kaizen dilakukan secara kontinyu\n3. Operator dan leader mengetahui action plan dari kaizen.\n(masa berlaku 3 bulan per kaizen)"},{"n":21,"t":"Follow up CAPA telah dilakukan sesuai rencana","r":"CAPA Customer complain, audit internal, dan ketidaksesuaian lainnya:\n1. Pengisian CAPA lengkap, logis, dan diverifikasi oleh SPV/Leader & Dept head\n2. Action plan CAPA efektif (issue tidak berulang)\n3. Evidence harus terlampir (foto, data, daftar hadir dll)"},{"n":22,"t":"Problem yang sama tidak terulang","r":"1. Defect mingguan tidak berulang dari report reject workcenter dan inspeksi QC (jika di atas standar ppm)"},{"n":23,"t":"Performance Monitoring In Process","r":"1. Setiap area memiliki papan monitoring performance\n2. Papan performance di-update daily & weekly\n3. Pengisian papan performance lengkap"},{"n":24,"t":"Tidak ada permintaan sortir pada next process","r":"Cek instruksi \"sortir next process\" pada label yang tertempel di barang."},{"n":25,"t":"Defect tidak ditemukan pada next process","r":"1. Defect setiap proses produksi yang ditemukan next process tidak melebihi standar PPM\n2. Defect proses produksi tidak ditemukan di proses inspeksi QC (patrol, outgoing, full lot)"},{"n":26,"t":"Analisa penyebab masalah lengkap Man-Method-Machine","r":"Analisa masalah pada NCR/CAPAR lengkap dan logis"},{"n":27,"t":"Tidak ada komplain external","r":"Cek komplain  / inspeksi eksternal"},{"n":28,"t":"Trend quality membaik","r":"PPM reject atau temuan inspeksi menurun / di bawah standar"},{"n":29,"t":"(QAFA) Barang tidak menghalangi area jalan","r":"1. WIP/barang tidak berada di area jalan dan jalur evakuasi\n2. Tidak menghalangi/block APAR, Hydrant, dan panel listrik"},{"n":30,"t":"(QAFA) Barang tidak mepet tembok","r":"Minimal 30 cm dari tembok"},{"n":31,"t":"(QAFA) Ventilasi/sirkulasi udara cukup","r":"kipas menyala"},{"n":32,"t":"Barang dan tempatnya ada label atau tanda","r":"1. WIP & hasil finished goods pada palet/ green bin harus ada label identitas dan area segregasi yang jelas. (Accept, hold, reject, FSC/NON FSC)\n2. Sharp tools harus ada identitas yang terdaftar di IE\n3. Wadah chemical diberi identitas yang jelas dan label hazard sesuai\n4. Wadah non- chemical/ WIP/Finished Goods diberi identitas yang jelas sesuai dengan fungsinya\n5. Material yg tersimpan di area produksi ada label yang jelas"},{"n":33,"t":"Alat ukur yang digunakan sesuai standar","r":"Alat ukur ada label kalibrasi dan tidak kadarluarsa"},{"n":34,"t":"Hanya WIP yang akan diproses yang ada di area kerja","r":"WIP terdaftar di RHHP"},{"n":35,"t":"(QAFA) Kondisi barang & tools yang digunakan baik dan disimpan dengan baik (teratur)","r":"1. Alas WIP/Finished Goods di palet & meja kerja bersih dari debu, jejak sepatu, dan kotoran lainnya\n2. Alas WIP/Finished Goods menggunakan sisi non-print\n3. Tempat barang tidak menggunakan produk customer, tidak rusak, dan digunakan sesuai fungsinya.\n4. Barang& tools yang disimpan rapih dan sesuai dengan tempatnya.\n5. Lampu meja kerja menyala dengan optimal (tidak redup & mati)"},{"n":36,"t":"Tidak ada makanan dan minuman yang berwarna di area produksi","r":""},{"n":37,"t":"Barang & tools yang digunakan tidak berpotensi mengandung phtalate","r":"Cek dengan incoming barang & tools yang digunakan sudah pass PH"},{"n":38,"t":"Tidak ada debu tebal, kotor, berkarat, atau sarang laba-laba","r":"1. Mesin, WIP/Finished Goods, tools, & barang lain tidak berdebu (di-wrapping), berkarat, dan ada sarang laba-laba, wrapping\n2. Wadah, secondary contaiment, alas lantai tidak kotor"},{"n":39,"t":"Tidak ada resiko safety (Produksi)","r":"1. Secondary contaiment pada benda cair\n2. Posisi palet bersandar pada barang\n3. Ada potensi karyawan tidak safety (palet bersandar, lampu meja kerja tidak terkait dengan benar, tidak memakai APD, kabel menjuntai)\n4. MSDS chemical tertempel dan menggunakan bahasa indo 26 bab/point\n4. Die block tidak pada tempatnya \n5. Safety issue pada mesin (oli bocor, pintu mesin tidak tertutup rapat, tombol &part-part mesin rusak/hilang, tidak ada getaran tak terduga, panas berlebihan)\n6. Kontaminasi issue \n7. Operator tidak boleh memakai kutek, aksesories tangan (gelang, cincin, dll)\nDLL (selain di list ini jika ada safety issue tetap temuan)"}];

